window.FILM_WORK_PROMPTS={"work_id":"src-162a5aaa5fe484aa","records":[{"work_id":"src-162a5aaa5fe484aa","frame_id":"FG-d891694f3aeec877","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/In_Time_07.jpg","source_page":"https://film-grab.com/2026/06/22/in-time/","scene":"一名短发男子位于画面中央，身穿深色立领外套，神情严肃。背景为昏暗的室内空间，上方横贯着明亮的长条形荧光灯管，下方隐约可见模糊的台面轮廓。","analysis":"画面采用中心构图，人物上半身占据画面主要位置，头部位于画面上三分之一处。镜头视角接近平视，人物面部受光均匀，眼神直视前方。背景中的长条灯管发出冷白色强光，形成横向视觉引导线，与人物深色衣物形成强烈明暗对比。整体色调偏冷，背景虚化处理突出了前景人物的清晰度。","prompt":"一名留着极短寸头的年轻男子，面部轮廓清晰，神情凝重且严肃，身穿深色立领夹克，内搭深蓝色衬衫。人物位于画面正中，仅显示上半身。背景是昏暗的室内环境，上方横贯着两根平行的长条形荧光灯管，发出刺眼的冷白色光芒，在人物头部后方形成高光。背景下方有模糊的暗红色墙面和类似玻璃器皿的虚化轮廓。整体画面色调偏青冷，光影对比强烈，营造出一种压抑、冷峻的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T07:02:05-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/In_Time_07.jpg","observed_dimensions":[1920,816],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.169,"observed_resolution":"normal","observation_limits":[],"id":"VP-7781462fe324b60c","origin":"visual"},{"work_id":"src-162a5aaa5fe484aa","frame_id":"FG-a87db2b7a4f1e0dc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/In_Time_20.jpg","source_page":"https://film-grab.com/2026/06/22/in-time/","scene":"一名身穿黑色燕尾服、佩戴黑色领结的男子，内搭白色衬衫，位于画面中央。背景为昏暗的室内环境，可见模糊的金色装饰物、反光器皿及右侧的浅色石柱。","analysis":"画面主体为男子的上半身，头部及肩部占据画面中心约三分之一区域。镜头采用平视角度，背景呈现明显的虚化效果，突出了前景人物。光线从上方投射，在人物面部形成柔和的明暗过渡，背景中散布着暖黄色的散景光斑，整体色调偏暖且对比度适中。","prompt":"一名深色短发男子的上半身肖像，他身穿黑色燕尾服，内搭白色褶皱衬衫并系着黑色领结。人物面部表情平静，眼神直视前方，皮肤在暖光下呈现自然质感。背景处于失焦状态，左侧可见模糊的深色墙面与金色浮雕装饰，右侧有一根浅色石柱，人物身后散布着数个明亮的暖黄色圆形光斑，营造出一种古典且略带神秘的室内氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T07:02:14-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/In_Time_20.jpg","observed_dimensions":[1920,816],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.188,"observed_resolution":"normal","observation_limits":[],"id":"VP-589c0db07bf2c62b","origin":"visual"},{"work_id":"src-162a5aaa5fe484aa","frame_id":"FG-7ec4c93229cddf8e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/In_Time_33.jpg","source_page":"https://film-grab.com/2026/06/22/in-time/","scene":"昏暗室内，一男一女相对而坐，两人均低头注视手中发绿光的设备，背景是透光的菱形网格屏风，右侧可见金属链条。","analysis":"画面采用剪影式构图，人物面部及身体细节隐没在黑暗中，仅保留轮廓。左侧男性头部光秃，右侧女性为短发，两人上半身占据画面主体。背景屏风透光，形成密集的菱形纹理，与前景黑色剪影形成强烈明暗对比。设备发出的绿色荧光在黑暗中清晰可见，成为画面中唯一的冷色光源。","prompt":"昏暗环境下的双人剪影，左侧光头男性与右侧短发女性相对而坐，两人均低头注视手中设备。设备屏幕发出幽绿荧光，照亮局部。背景为透光的菱形网格屏风，光线从后方透出，形成密集纹理。右侧边缘可见垂直悬挂的金属链条。整体色调偏暖黄，人物呈黑色剪影，绿色光点与背景暖光形成冷暖对比，氛围神秘静谧。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T07:02:24-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/In_Time_33.jpg","observed_dimensions":[1920,816],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.242,"observed_resolution":"normal","observation_limits":[],"id":"VP-4e9403b50960b871","origin":"visual"},{"work_id":"src-162a5aaa5fe484aa","frame_id":"FG-82925cbaf59245af","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/In_Time_46.jpg","source_page":"https://film-grab.com/2026/06/22/in-time/","scene":"昏暗旅馆房间内，一男一女相对坐在铺着橙黄色床单的床上，男子手持牌，右侧小桌上放着两把手枪，墙面贴着红底金色花纹壁纸。","analysis":"画面采用略微俯视的视角，床铺占据画面中心及下方大部分区域。两人均可见上半身及腿部，男子背对镜头侧坐，女子面向镜头侧坐。床头柜上的台灯发出暖黄光，照亮了人物面部和床铺中心，四周环境较暗，形成明显的明暗对比。右侧小桌上的手枪在暗部中轮廓清晰。","prompt":"昏暗的旅馆房间，红底金色花纹壁纸，一男一女相对坐在铺着橙黄色床单的床上。男子穿灰色衬衫，背对镜头侧坐，手持扑克牌；女子穿黑色皮衣，面向镜头侧坐。床头柜上有一盏亮着的台灯，发出暖黄光。床上散落着几张扑克牌。右侧有一张深色小桌，上面放着两把手枪。房间光线昏暗，主要光源来自床头灯，营造出一种紧张而私密的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T07:02:34-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/In_Time_46.jpg","observed_dimensions":[1920,816],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.212,"observed_resolution":"normal","observation_limits":[],"id":"VP-6d852a9e61a6c664","origin":"visual"},{"work_id":"src-162a5aaa5fe484aa","frame_id":"FG-f9e2d41cceee5119","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/In_Time_59.jpg","source_page":"https://film-grab.com/2026/06/22/in-time/","scene":"俯视视角下，数十名穿着各色运动服的人物在灰色水泥地面上围成紧密的同心圆，手臂相互交叠，左侧可见带有白色字母的绿色金属围栏结构。","analysis":"画面采用垂直俯视构图，人物呈放射状向中心聚拢，形成强烈的几何秩序感。由于视角极高，人物主要呈现头部和肩背部，四肢在中心区域交错，难以分辨具体面部特征。光线均匀柔和，无明显阴影，色彩以人物衣着的蓝、黄、黑、灰为主，与冷灰色地面形成对比。","prompt":"垂直俯视视角的户外场景，灰色水泥地面上聚集着数十名人物，他们紧密地围成多层同心圆，手臂在中心区域相互交叠，呈现出团结或仪式感的姿态。人物穿着深蓝色、黄色、黑色及灰色的运动风格服装，头部和肩背部清晰可见，面部细节因角度而模糊。画面左侧边缘是一个绿色的金属围栏结构，上面带有白色的装饰性字母图案。整体光线均匀，色调偏冷，人物密集排列形成复杂的纹理，周围留有少量空旷的地面空间。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T07:02:45-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/In_Time_59.jpg","observed_dimensions":[1920,816],"source_thumbnail_dimensions":[500,213],"source_image_match_mae":0.245,"observed_resolution":"normal","observation_limits":[],"id":"VP-b3491539f2bd1b11","origin":"visual"}]};